@push('scripts')<script>const c=document.getElementById('category'),s=document.getElementById('subcategory');function filterSubcategories(){const category=c.value;Array.from(s.options).forEach(o=>{if(o.value)o.hidden=o.dataset.category!==category});if(s.selectedOptions[0]?.hidden)s.value=''}c.addEventListener('change',filterSubcategories);filterSubcategories()</script>@endpush
